catalog_script_client.script:
function onChange(control, oldValue, newValue, isLoading, isTemplate) {
    if (isLoading || isTemplate) {
        return;
    }

    g_form.hideFieldMsg('preferred_datetime', true);

    // Agar field empty ya clear kar diya gaya hai
    if (!newValue) {
        return;
    }

    // Space ko 'T' se replace karke Date object banana (aur ISO string ke saath safe handling)
    var formattedDate = newValue.indexOf('T') === -1 ? newValue.replace(' ', 'T') : newValue;
    var selectedDateTime = new Date(formattedDate);
    var now = new Date();

    if (isNaN(selectedDateTime.getTime())) {
        g_form.clearValue('preferred_datetime');
        g_form.showFieldMsg('preferred_datetime', 'Please enter a valid date and time.', 'error');
        return;
    }

    // Past ya current time hone par value clear karke message dikhana
    if (selectedDateTime <= now) {
        g_form.clearValue('preferred_datetime');
        g_form.showFieldMsg('preferred_datetime', 'The preferred date and time must be in the future.', 'error');
    }
}
